<?php require __DIR__.'/../includes/functions.php'; if(!admin_configured()){ header('Location: ../setup.php'); exit; } $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $c=config(); if(password_verify($_POST['password']??'', $c['admin_password_hash'])){ $_SESSION['admin_logged_in']=true; header('Location: index.php'); exit; } else $error='Wrong password.'; } ?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="../assets/styles.css"></head><body class="admin-bg"><main class="login-card"><h1>Admin login</h1><?php if(isset($_GET['setup'])): ?><div class="success-msg">Setup complete. Log in now.</div><?php endif; ?><?php if($error): ?><div class="alert"><?=h($error)?></div><?php endif; ?><form method="post"><input type="password" name="password" placeholder="Admin password" required><button class="btn primary wide">Log in</button></form><p><a href="../index.php">← Back to website</a></p></main></body></html>